export function activate(context: vscode.ExtensionContext) {
    console.log('POC Trae WebSocket Extension is now active!');

    server = http.createServer((req, res) => {
        if (req.method === 'GET' && req.url === '/health') {
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ status: 'ok', worker: 'Trae WebSocket Engine' }));
            return;
        }

        if (req.method === 'GET' && req.url === '/api/commands') {
            void vscode.commands.getCommands(true).then(
                commands => {
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ total: commands.length, commands }));
                },
                (err: unknown) => {
                    res.writeHead(500, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ error: String(err) }));
                }
            );
            return;
        }

        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not Found (Please use ws://...)');
    });

    try {
        wss = new WebSocket.Server({ server });

        wss.on('connection', (ws: WebSocket) => {
            console.log('Codex Brain connected via WebSocket!');
            ws.send(JSON.stringify({ type: 'connected', message: 'Hello from Trae Worker!' }));

            const diagDisposable = vscode.languages.onDidChangeDiagnostics(event => {
                const allDiagnostics = event.uris.map(uri => {
                    const diags = vscode.languages.getDiagnostics(uri);
                    return {
                        file: uri.fsPath,
                        errors: diags
                            .filter(d => d.severity === vscode.DiagnosticSeverity.Error)
                            .map(d => ({
                                line: d.range.start.line + 1,
                                message: d.message
                            }))
                    };
                }).filter(group => group.errors.length > 0);

                if (allDiagnostics.length > 0) {
                    ws.send(JSON.stringify({
                        type: 'system_diagnostics_report',
                        data: allDiagnostics
                    }));
                }
            });
            context.subscriptions.push(diagDisposable);

            const saveDisposable = vscode.workspace.onDidSaveTextDocument(doc => {
                ws.send(JSON.stringify({
                    type: 'file_saved',
                    file: doc.uri.fsPath,
                    content_preview: doc.getText().substring(0, 150) + '... '
                }));
            });
            context.subscriptions.push(saveDisposable);

            ws.on('message', async (message: string) => {
                try {
                    const payload = JSON.parse(message.toString()) as IncomingPayload;
                    console.log('Received payload:', payload);

                    if (payload.action === 'trigger_task') {
                        const taskPayload = payload as TriggerTaskPayload;
                        const subagent = (taskPayload.subagent ?? 'worker').trim();
                        const prompt = (taskPayload.prompt ?? '').trim();

                        vscode.window.showInformationMessage(`[Trae Worker] 收到拦截指令，正将其推入黑盒聊天流...`);

                        try {
                            // 1. 弹出右侧的 Trae AI 面板
                            await vscode.commands.executeCommand('workbench.action.chat.openInSidebar');
                            await new Promise(resolve => setTimeout(resolve, 800));

                            // 2. 将 Codex 下发的疯狂提示词直接写入系统剪贴板
                            await vscode.env.clipboard.writeText(prompt);

                            // 3. 强制清空之前可能残留的对话记录（开一个新窗）
                            try {
                                await vscode.commands.executeCommand('workbench.action.chat.newChat');
                            } catch (e) { }
                            await new Promise(resolve => setTimeout(resolve, 500));

                            // 4. 将焦点再次强制锁定（防止弹窗失焦）
                            await vscode.commands.executeCommand('workbench.action.chat.openInSidebar');
                            await new Promise(resolve => setTimeout(resolve, 300));

                            // 5. 调用系统自带粘贴
                            await vscode.commands.executeCommand('editor.action.clipboardPasteAction');
                            await new Promise(resolve => setTimeout(resolve, 500));

                            // 6. 模拟人类按下回车键，油门踩死！
                            await vscode.commands.executeCommand('workbench.action.chat.submit');

                            ws.send(JSON.stringify({
                                type: 'action_receipt',
                                status: 'success',
                                message: `💥 [宏指令注入成功] Codex 的越狱指令已被强行推入 Trae 工作流并敲击了回车！准备迎接风暴！`,
                                payload: taskPayload
                            }));
                        } catch (e) {
                            ws.send(JSON.stringify({
                                type: 'action_receipt',
                                status: 'error',
                                message: `宏指令注入失败: ${String(e)}`
                            }));
                        }

                        return;
                    }

                    if (payload.action === 'execute_command') {
                        const executePayload = payload as ExecuteCommandPayload;
                        const command = (executePayload.command ?? '').trim();
                        if (!command) {
                            ws.send(JSON.stringify({
                                type: 'command_result',
                                status: 'failed',
                                message: 'command is required'
                            }));
                            return;
                        }

                        const args = Array.isArray(executePayload.args) ? executePayload.args : [];
                        const result = await executeCommandSafely(command, args);
                        ws.send(JSON.stringify({
                            type: 'command_result',
                            status: result.ok ? 'success' : 'failed',
                            command,
                            args,
                            result: result.value,
                            error: result.error
                        }));
                        return;
                    }

                    if (payload.action === 'auto_select_model') {
                        const modelPayload = payload as AutoSelectModelPayload;
                        const result = await autoSelectModel(modelPayload);
                        ws.send(JSON.stringify({
                            type: 'model_selection_result',
                            status: result.setConfigSucceeded || modelPayload.dryRun ? 'success' : 'partial',
                            data: result
                        }));
                        return;
                    }

                    const actionName = (payload as { action?: string }).action ?? 'unknown';
                    ws.send(JSON.stringify({ type: 'error', message: `Unsupported action: ${actionName}` }));
                } catch {
                    ws.send(JSON.stringify({ type: 'error', message: 'Invalid command payload' }));
                }
            });

            ws.on('close', () => {
                console.log('Codex Brain disconnected');
            });
        });

        server.on('error', (err: any) => {
            if (err.code === 'EADDRINUSE') {
                vscode.window.showErrorMessage(`Trae 报警: 9090 端口已被占用！很可能是上一次加载的僵尸进程没死透。请彻底关闭所有 Trae 窗口重试。`);
            } else {
                vscode.window.showErrorMessage(`Trae 通道异常: ${err.message}`);
            }
        });

        server.listen(9090, '127.0.0.1', () => {
            console.log('Trae WebSocket API Server listening on ws://127.0.0.1:9090');
            vscode.window.showInformationMessage('Trae WebSocket channel active (0.0.8) on 9090 🚀');
        });
    } catch (err) {
        vscode.window.showErrorMessage('Trae channel startup failed: ' + String(err));
    }
}

