function normalizeIntent(prompt: string, modeHint?: ModelIntent): ModelIntent {
    if (modeHint) {
        return modeHint;
    }

    const lower = prompt.toLowerCase();
    const hasReasoning = REASONING_KEYWORDS.some(key => lower.includes(key));
    const hasCoding = CODING_KEYWORDS.some(key => lower.includes(key));
    const hasSpeed = SPEED_KEYWORDS.some(key => lower.includes(key));

    if (hasReasoning) {
        return 'reasoning';
    }
    if (hasCoding) {
        return 'coding';
    }
    if (hasSpeed) {
        return 'speed';
    }
    return 'coding';
}

function isLikelyModelName(name: string): boolean {
    if (!MODEL_NAME_PATTERN.test(name)) {
        return false;
    }

    const lower = name.toLowerCase();
    if (lower.includes('http://') || lower.includes('https://') || lower.endsWith('.svg')) {
        return false;
    }
    if (lower.includes('sidebar') || lower.includes('extension') || lower.includes('avatar')) {
        return false;
    }

    return /[0-9]/.test(name) || /[-_/.]/.test(name);
}

function isInternalUtilityModel(modelName: string): boolean {
    const lower = modelName.toLowerCase();
    if (INTERNAL_MODEL_EXACT.has(lower)) {
        return true;
    }
    return INTERNAL_MODEL_PREFIXES.some(prefix => lower.startsWith(prefix));
}

function collectModelCandidates(input: unknown, out: Set<string>): void {
    if (typeof input === 'string') {
        if (MODEL_HINT_REGEX.test(input) && input.length <= 120 && isLikelyModelName(input)) {
            out.add(input);
        }
        return;
    }

    if (Array.isArray(input)) {
        for (const value of input) {
            collectModelCandidates(value, out);
        }
        return;
    }

    if (input && typeof input === 'object') {
        const obj = input as Record<string, unknown>;
        for (const value of Object.values(obj)) {
            collectModelCandidates(value, out);
        }
    }
}

function normalizeModelList(models: Iterable<string>): string[] {
    const dedup = new Map<string, string>();
    for (const model of models) {
        if (!isLikelyModelName(model)) {
            continue;
        }
        const lower = model.toLowerCase();
        if (!dedup.has(lower)) {
            dedup.set(lower, model);
        }
    }
    return Array.from(dedup.values()).sort((a, b) => a.localeCompare(b));
}

function scoreModel(modelName: string, intent: ModelIntent): number {
    const name = modelName.toLowerCase();
    let score = 0;

    if (isInternalUtilityModel(name)) {
        score -= 200;
    }

    const priorityList = INTENT_MODEL_PRIORITIES[intent];
    const priorityIndex = priorityList.indexOf(name);
    if (priorityIndex >= 0) {
        score += (priorityList.length - priorityIndex) * 30;
    }

    if (intent === 'coding') {
        if (name.includes('coder') || name.includes('code')) {
            score += 14;
        }
        if (name.includes('qwen') || name.includes('deepseek') || name.includes('doubao-seed')) {
            score += 6;
        }
    }

    if (intent === 'reasoning') {
        if (name.includes('deepseek') || name.includes('kimi')) {
            score += 12;
        }
        if (name.includes('glm-5') || name.includes('m2.5')) {
            score += 5;
        }
    }

    if (intent === 'speed') {
        if (name.includes('glm-4.7') || name.includes('doubao_1_8')) {
            score += 10;
        }
        if (name.includes('qwen-3.5') || name.includes('m2') || name.includes('k2')) {
            score += 4;
        }
    }

    if (name.includes('preview') || name.includes('experimental')) {
        score -= 2;
    }

    return score;
}

function pickBestModel(models: string[], intent: ModelIntent): string | null {
    if (models.length === 0) {
        return null;
    }

    const nonInternal = models.filter(model => !isInternalUtilityModel(model));
    const pool = nonInternal.length > 0 ? nonInternal : models;

    let best: { name: string; score: number } | null = null;
    for (const model of pool) {
        const score = scoreModel(model, intent);
        if (!best || score > best.score) {
            best = { name: model, score };
        }
    }
    return best?.name ?? pool[0];
}

function safeStringify(value: unknown): string {
    try {
        return JSON.stringify(value);
    } catch {
