      reject(error);
    };

    function cleanup() {
      clearTimeout(timer);
      ws.off('open', onOpen);
      ws.off('error', onError);
    }

    ws.on('open', onOpen);
    ws.on('error', onError);
  });
}

function waitForMessage(ws, predicate, timeoutMs = 12000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('websocket message timeout'));
    }, timeoutMs);

    const onMessage = (raw) => {
      let parsed;
      try {
        parsed = JSON.parse(raw.toString());
      } catch {
        return;
      }

      if (!predicate(parsed)) {
        return;
      }
      cleanup();
      resolve(parsed);
    };

    const onError = (error) => {
      cleanup();
      reject(error);
    };

    function cleanup() {
      clearTimeout(timer);
      ws.off('message', onMessage);
      ws.off('error', onError);
    }

    ws.on('message', onMessage);
    ws.on('error', onError);
  });
}

async function main() {
  const results = [];
  const observations = {};

  async function runCase(name, fn) {
    try {
      const data = await fn();
      results.push({ name, status: 'passed' });
      return data;
    } catch (error) {
      results.push({ name, status: 'failed', error: String(error) });
      throw error;
    }
  }

  let ws;
  let originalConfig = null;
  let hasSetConfig = false;

  try {
    const health = await runCase('HTTP /health 可用', async () => {
      const response = await httpRequest('/health');
      assert.equal(response.statusCode, 200);
      const body = JSON.parse(response.body);
      assert.equal(body.status, 'ok');
      return body;
    });
    observations.health = health;

    const commandsMeta = await runCase('HTTP /api/commands 返回命令清单', async () => {
      const response = await httpRequest('/api/commands');
      assert.equal(response.statusCode, 200);
      const body = JSON.parse(response.body);
      assert.ok(Array.isArray(body.commands));
      assert.ok(body.commands.length > 0);
      return body;
    });

    observations.commandTotal = commandsMeta.total;
    hasSetConfig = commandsMeta.commands.includes('icube.extended.integrations.llm.setConfig');
    observations.hasGetConfig = commandsMeta.commands.includes('icube.extended.integrations.llm.getConfig');
    observations.hasSetConfig = hasSetConfig;
    observations.hasOpenPicker = commandsMeta.commands.includes('workbench.action.chat.openModelPicker');

    await runCase('HTTP 未知路径返回 404', async () => {
      const response = await httpRequest('/does-not-exist');
      assert.equal(response.statusCode, 404);
      assert.ok(response.body.includes('Not Found'));
    });

    ws = new WebSocket('ws://127.0.0.1:9090');
    await waitForWsOpen(ws);

    await runCase('WebSocket 握手消息', async () => {
      const message = await waitForMessage(ws, (m) => m.type === 'connected');
      assert.equal(message.message, 'Hello from Trae Worker!');
    });

    await runCase('非法 JSON 报文返回错误', async () => {
      ws.send('not-json-payload');
      const message = await waitForMessage(ws, (m) => m.type === 'error' && m.message === 'Invalid command payload');
      assert.equal(message.message, 'Invalid command payload');
    });

    await runCase('未知 action 返回错误', async () => {
      ws.send(JSON.stringify({ action: 'unknown_live_action' }));
      const message = await waitForMessage(ws, (m) => m.type === 'error' && String(m.message).includes('Unsupported action'));
      assert.ok(String(message.message).includes('unknown_live_action'));
    });

    await runCase('execute_command 缺少 command 参数时报错', async () => {
      ws.send(JSON.stringify({ action: 'execute_command', command: ' ' }));
      const message = await waitForMessage(ws, (m) => m.type === 'command_result' && m.status === 'failed' && m.message === 'command is required');
      assert.equal(message.message, 'command is required');
    });

    await runCase('execute_command 可调用 getConfig', async () => {
      ws.send(JSON.stringify({ action: 'execute_command', command: 'icube.extended.integrations.llm.getConfig' }));
      const message = await waitForMessage(ws, (m) => m.type === 'command_result' && m.command === 'icube.extended.integrations.llm.getConfig');
      assert.equal(message.status, 'success');
      originalConfig = message.result;
      assert.ok(message.result !== undefined);
    });

    await runCase('execute_command 调用未知命令走失败分支', async () => {
      ws.send(JSON.stringify({ action: 'execute_command', command: 'this.command.does.not.exist' }));
      const message = await waitForMessage(ws, (m) => m.type === 'command_result' && m.command === 'this.command.does.not.exist');
      assert.equal(message.status, 'failed');
      assert.ok(String(message.error || '').length > 0);
    });

    const dryRunReasoning = await runCase('auto_select_model dryRun=reasoning', async () => {
      ws.send(JSON.stringify({ action: 'auto_select_model', prompt: '请分析架构并进行深入推理', dryRun: true }));
      const message = await waitForMessage(ws, (m) => m.type === 'model_selection_result' && m.data && m.data.intent === 'reasoning');
      assert.equal(message.status, 'success');
      assert.equal(message.data.intent, 'reasoning');
      assert.equal(message.data.usedSetConfig, false);
      return message.data;
    });

    const dryRunCoding = await runCase('auto_select_model dryRun=coding', async () => {
      ws.send(JSON.stringify({ action: 'auto_select_model', prompt: '请写代码并修复 bug', dryRun: true }));
      const message = await waitForMessage(ws, (m) => m.type === 'model_selection_result' && m.data && m.data.intent === 'coding');
      assert.equal(message.status, 'success');
      assert.equal(message.data.intent, 'coding');
      return message.data;
    });

    observations.dryRunReasoningSelected = dryRunReasoning.selectedModel;
    observations.dryRunCodingSelected = dryRunCoding.selectedModel;

    if (hasSetConfig) {
      const nonDryRun = await runCase('auto_select_model 非 dryRun 切模分支', async () => {
        ws.send(JSON.stringify({ action: 'auto_select_model', modeHint: 'speed', dryRun: false }));
        const message = await waitForMessage(ws, (m) => m.type === 'model_selection_result' && m.data && m.data.intent === 'speed');
        assert.ok(message.status === 'success' || message.status === 'partial');
        return message.data;
      });
      observations.nonDryRunSpeedSelected = nonDryRun.selectedModel;
      observations.nonDryRunSetConfigSucceeded = nonDryRun.setConfigSucceeded;

      if (originalConfig !== null) {
        await runCase('恢复原始 LLM 配置', async () => {
          ws.send(JSON.stringify({
            action: 'execute_command',
            command: 'icube.extended.integrations.llm.setConfig',
            args: [originalConfig]
          }));
          const message = await waitForMessage(
            ws,
            (m) => m.type === 'command_result' && m.command === 'icube.extended.integrations.llm.setConfig'
          );
          assert.equal(message.status, 'success');
        });
      }
    }

    await runCase('trigger_task 返回 action_receipt', async () => {
      ws.send(JSON.stringify({
        action: 'trigger_task',
        subagent: 'qa-smoke',
        prompt: '这是 0.0.10 测试消息，请忽略。'
      }));
      const message = await waitForMessage(ws, (m) => m.type === 'action_receipt');
      assert.ok(message.status === 'success' || message.status === 'error');
      observations.triggerTaskStatus = message.status;
      observations.triggerTaskMessage = message.message;
    });
  } finally {
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.close();
    }
  }

  const passed = results.filter((r) => r.status === 'passed').length;
  const failed = results.filter((r) => r.status === 'failed').length;

  const report = {
    timestamp: new Date().toISOString(),
    passed,
    failed,
    total: results.length,
    observations,
    results
  };

  console.log(JSON.stringify(report, null, 2));

  if (failed > 0) {
    process.exit(1);
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
